import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3-dimensional benchmark function designed for ELA testing.

    This function combines a Rosenbrock-like term, a skewed exponential, and
    a sum of cosines to introduce different landscape characteristics.

    Formula:
        f(x) = rosenbrock(x) + skewed_exp(x) + cosine_term(x)

    where:
        rosenbrock(x) = sum(100.0 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2)
        skewed_exp(x) = np.exp(-np.sum(x)) * (1 + 0.433 * np.linalg.norm(x))
        cosine_term(x) = 0.864 * np.sum(np.cos(x))

    Domain: [-5, 5]^3
    """
    if len(x) != 3:
        raise ValueError("Input array x must have dimension 3.")

    def rosenbrock(x: np.ndarray) -> float:
        """Rosenbrock function."""
        return np.sum(100.0 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2) if len(x) > 1 else 0.0

    def skewed_exp(x: np.ndarray) -> float:
        """Skewed exponential function."""
        return np.exp(-np.sum(x)) * (1 + 0.433 * np.linalg.norm(x))

    def cosine_term(x: np.ndarray) -> float:
        """Sum of cosine functions."""
        return 0.864 * np.sum(np.cos(x))


    return rosenbrock(x) + skewed_exp(x) + cosine_term(x)
